"""Inspect the workspace: list files and show SQLite schemas if a DB is present."""
import os
import sqlite3

for entry in sorted(os.listdir(".")):
    full = os.path.join(".", entry)
    print(f"{'DIR ' if os.path.isdir(full) else 'FILE'} {entry}")

print("\n--- SQLite databases found ---")
for entry in sorted(os.listdir(".")):
    if entry.lower().endswith((".db", ".sqlite", ".sqlite3")):
        print(f"\nDatabase: {entry}")
        try:
            with sqlite3.connect(entry) as conn:
                cur = conn.cursor()
                tables = cur.execute(
                    "SELECT name FROM sqlite_master WHERE type='table' ORDER BY name"
                ).fetchall()
                for (table,) in tables:
                    print(f"\nTable: {table}")
                    for row in cur.execute(f"PRAGMA table_info({table})").fetchall():
                        print(f"  {row}")
        except sqlite3.Error as exc:
            print(f"  (not a readable SQLite DB: {exc})")

